  if(miniMapId!=cam.id){if(miniBitmap!=null)miniBitmap.recycle();miniBitmap=null;try(java.io.InputStream in=getContext().getAssets().open("maps/"+cam.id+"-image.png")){BitmapFactory.Options o=new BitmapFactory.Options();o.inSampleSize=4;o.inPreferredConfig=Bitmap.Config.RGB_565;miniBitmap=BitmapFactory.decodeStream(in,null,o);}catch(java.io.IOException ignored){}miniMapId=cam.id;}
