 public void showFrameOptions(){
  MyGLSurfaceView view=surface();if(view==null)return;LinearLayout list=new LinearLayout(getContext());list.setOrientation(1);list.setPadding((int)(20*dp),(int)(10*dp),(int)(20*dp),(int)(12*dp));
  TextView title=new TextView(getContext());title.setTypeface(font);title.setTextSize(20);title.setTextColor(0xffdce9e3);title.setText(zh?"画面帧率":"Frame rate");list.addView(title);
  TextView info=new TextView(getContext());info.setTypeface(font);info.setTextSize(12);info.setTextColor(0xffb5c9c0);float hz=view.getDisplay()==null?60:view.getDisplay().getRefreshRate();info.setText((zh?"当前屏幕 ":"Display ")+Math.round(hz)+" Hz\n"+(zh?"自动优先高刷。此处为目标上限，实际帧率由负载、温度及系统决定；降低上限可省电。对局速度不变。":"Auto prefers high refresh. This is a target limit; workload, heat and system policy control actual FPS. Lower limits save power. Game speed stays unchanged."));list.addView(info);
  AlertDialog dialog=new AlertDialog.Builder(getContext()).setView(list).setNegativeButton(zh?"返回":"Return",null).create();int pref=DisplayFrameRate.preference(getContext());
  for(int fps:DisplayFrameRate.choices(view.getDisplay())){Button button=new Button(getContext());button.setTypeface(font);button.setAllCaps(false);button.setText((pref==fps?"✓  ":"")+(fps==0?(zh?"自动 · 优先高刷":"Auto · high refresh"):fps+" FPS"));button.setTextColor(pref==fps?0xffb6dfcc:0xffd5dfda);button.setOnClickListener(v->{DisplayFrameRate.preference(getContext(),fps);view.refreshRate();invalidate();dialog.dismiss();});list.addView(button);}
  dialog.show();dialog.getButton(-2).setTypeface(font);dialog.getButton(-2).setTextColor(0xffa9d8c5);
 }
    public void showGuide(){
        ScrollView scroll=new ScrollView(getContext());LinearLayout list=new LinearLayout(getContext());list.setOrientation(LinearLayout.VERTICAL);list.setPadding((int)(16*dp),(int)(8*dp),(int)(16*dp),(int)(12*dp));scroll.addView(list);
        TextView intro=new TextView(getContext());intro.setTypeface(font);intro.setFontVariationSettings("'wght' 500");intro.setText(zh?"每波随机1至6件，强效果与反制成对出现，单数多一件防御道具。回溯每局最多刷一次。全部吞噬后才刷下一波，残血道具不会被定时替换。道具会阻挡粒子，拥有1200血量；围住边缘持续吞噬，逐渐变小，约2.1秒以上才生效，离开后保留残血；争夺时累计吞噬最多的存活队获得。点击或拖动地图设置触摸点，粒子跟随触摸点移动；松手保留落点。地图跟随己方粒子，按住边缘可持续引导移动；松手保留落点；支持五指点按。传送可直接点小地图；死亡、朋友点击底部卡片选队伍。单机暂停时冻结计时，联机图鉴不暂停房间。":"Random1–6 per wave; powers have same-wave counters, with a defensive odd extra. Rewind appears once per match. Finish every pickup before the next wave; partial pickups never time out. Items block particles with solid bodies that shrink while devoured. They have 1200 HP and require at least 2.1 simulation seconds of devouring; progress stays when you leave. The living team with most contribution receives it. Tap or drag anywhere on the map to set touch targets. Particles follow the targets, which stay on release. The camera gently follows your army with a small look-ahead. Hold near the edge to keep guiding it. Release keeps the last destination. Up to five fingers are supported. Teleport directly through the minimap; Death and Friend select a team through the stored card. Solo pause freezes timers; network guide does not pause the room.");intro.setTextColor(0xffdce5de);list.addView(intro);
        for(int i=0;i<20;i++){
            LinearLayout row=new LinearLayout(getContext());row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(0,(int)(12*dp),0,(int)(12*dp));
            ImageView image=new ImageView(getContext());image.setImageDrawable(icons[i].getConstantState().newDrawable());row.addView(image,new LinearLayout.LayoutParams((int)(44*dp),(int)(44*dp)));
            TextView label=new TextView(getContext());label.setTypeface(font);label.setFontVariationSettings("'wght' 500");label.setTextSize(14);label.setTextColor(0xffe7eee8);label.setPadding((int)(12*dp),0,0,0);label.setText(String.format(java.util.Locale.ROOT,"%02d · %s\n",i+1,names[i])+descriptions[i]);row.addView(label,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1));list.addView(row);
        }
        TextView title=new TextView(getContext());title.setTypeface(font);title.setFontVariationSettings("'wght' 600");title.setTextSize(19);title.setPadding((int)(20*dp),(int)(16*dp),0,(int)(8*dp));title.setTextColor(0xfff0e5d0);title.setText(zh?"20种战场道具":"20 battlefield items");
        AlertDialog d=new AlertDialog.Builder(getContext()).setCustomTitle(title).setView(scroll).setPositiveButton(zh?"返回对局":"Return",null).create();d.show();d.getButton(AlertDialog.BUTTON_POSITIVE).setTextColor(0xffa9d8c5);d.getButton(AlertDialog.BUTTON_POSITIVE).setTypeface(font);d.getButton(AlertDialog.BUTTON_POSITIVE).setFontVariationSettings("'wght' 600");
    }
